import{_ as t,o as n,c as i,a2 as r}from"./chunks/framework.mRCPFc5l.js";const b=JSON.parse('{"title":"Was sind Seiten","description":"Seiten und Portale in ApptiveGrid — aus Blöcken zusammengesetzte Oberflächen.","frontmatter":{"title":"Was sind Seiten","description":"Seiten und Portale in ApptiveGrid — aus Blöcken zusammengesetzte Oberflächen."},"headers":[],"relativePath":"seiten/was-sind-seiten.md","filePath":"seiten/was-sind-seiten.md","lastUpdated":1786024399000}'),a={name:"seiten/was-sind-seiten.md"};function s(l,e,o,d,h,u){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="was-sind-seiten" tabindex="-1">Was sind Seiten <a class="header-anchor" href="#was-sind-seiten" aria-label="Permalink to &quot;Was sind Seiten&quot;">​</a></h1><p>Eine <strong>Seite</strong> ist eine frei zusammengesetzte Oberfläche. Sie bauen sie aus <strong>Blöcken</strong>: Überschriften, Textabsätzen, Bildern, Eingabefeldern, eingebetteten Ansichten, Auswertungen und Layout-Containern.</p><p>Veröffentlichen Sie eine Seite, entsteht ein <strong>Portal</strong> — eine eigenständige Webadresse, die Sie teilen oder in Ihre Website einbetten können.</p><p>Der Leerzustand im Seiten-Bereich beschreibt es so:</p><blockquote><p><em>Willkommen in deinem Bereich „Seiten&quot;. Hier kannst du all deine Informationen, Notizen und Dokumentationen festhalten.</em></p></blockquote><p>Das trifft aber nur den einfachsten Fall. Seiten können deutlich mehr.</p><h2 id="wofur-seiten-gut-sind" tabindex="-1">Wofür Seiten gut sind <a class="header-anchor" href="#wofur-seiten-gut-sind" aria-label="Permalink to &quot;Wofür Seiten gut sind&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Anwendung</th><th>Was Sie dafür brauchen</th></tr></thead><tbody><tr><td>Interne Dokumentation, Notizen, Handbücher</td><td>Text- und Überschriften-Blöcke</td></tr><tr><td>Dashboard mit Kennzahlen</td><td>Zähler, Summenkarte, Donut-Diagramm</td></tr><tr><td>Kundenportal mit Datenübersicht</td><td>eingebettete Grid-Ansicht</td></tr><tr><td>Eingabemaske mit eigenem Aufbau</td><td>Formularfeld-Blöcke</td></tr><tr><td>Startseite für einen Prozess</td><td>Button- oder QR-Code-Block auf einen Flow</td></tr><tr><td>Oberfläche innerhalb eines Flows</td><td>Seite, die ein Flow-Schritt anzeigt</td></tr></tbody></table><h2 id="seite-formular-oder-ansicht" tabindex="-1">Seite, Formular oder Ansicht? <a class="header-anchor" href="#seite-formular-oder-ansicht" aria-label="Permalink to &quot;Seite, Formular oder Ansicht?&quot;">​</a></h2><p>Drei Werkzeuge, die sich überschneiden. Die Faustregel:</p><table tabindex="0"><thead><tr><th>Sie wollen …</th><th>Nehmen Sie</th></tr></thead><tbody><tr><td>Daten erfassen, schnell und ohne Gestaltungsaufwand</td><td><a href="/formulare/formular-erstellen">Formular</a></td></tr><tr><td>Daten anzeigen und bearbeiten, tabellarisch</td><td><a href="/ansichten/was-ist-eine-ansicht">Ansicht</a></td></tr><tr><td>Mehreres kombinieren: Text, Daten, Eingabe, Auswertung</td><td><strong>Seite</strong></td></tr><tr><td>Eine Oberfläche mit eigenem Aufbau und Layout</td><td><strong>Seite</strong></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Eine Seite kann ein Formular ersetzen</p><p>Seiten kennen dieselben Eingabefelder wie Formulare — und zusätzlich Layout, Text, Bilder und eingebettete Daten. Wenn ein Formular gestalterisch an Grenzen stößt, ist eine Seite der nächste Schritt.</p><p>Für einfache Erfassung bleibt das Formular schneller: Felder auswählen, teilen, fertig.</p></div><h2 id="seiten-und-blocke" tabindex="-1">Seiten und Blöcke <a class="header-anchor" href="#seiten-und-blocke" aria-label="Permalink to &quot;Seiten und Blöcke&quot;">​</a></h2><p>Eine Seite ist ein <strong>Baum aus Blöcken</strong>. Blöcke können andere Blöcke enthalten — ein Layout-Block ordnet die enthaltenen Blöcke nebeneinander oder untereinander an, ein Tab-Layout zeigt Unterseiten als Reiter.</p><p>Die Blockauswahl gliedert sich in drei Gruppen:</p><ul><li><strong>Basis-Blöcke</strong> — Absatz, Überschriften, Bild, Unterseite, Layouts</li><li><strong>Spezial-Blöcke</strong> — eingebettete Ansichten, Auswertungen, Buttons, HTML</li><li><strong>Formularfeld-Blöcke</strong> — alle Eingabefelder</li></ul><p>→ <a href="/seiten/bloecke">Blockübersicht</a> · <a href="/referenz/blocktypen">Blocktypen-Referenz</a></p><h2 id="unterseiten" tabindex="-1">Unterseiten <a class="header-anchor" href="#unterseiten" aria-label="Permalink to &quot;Unterseiten&quot;">​</a></h2><p>Eine Seite kann <strong>Unterseiten</strong> enthalten. Damit bauen Sie mehrstufige Strukturen — ein Handbuch mit Kapiteln, ein Portal mit mehreren Bereichen.</p><p>Zwei Layout-Blöcke stellen Unterseiten besonders dar:</p><ul><li><strong>Tab-Layout</strong> — <em>Unterseiten als Tabs anzeigen</em></li><li><strong>Stepper-Layout</strong> — <em>Unterseiten als Schritte anzeigen</em></li></ul><p>Das Stepper-Layout eignet sich für geführte Abläufe: Der Nutzer arbeitet sich Schritt für Schritt durch.</p><h2 id="die-zwei-modi-einer-seite" tabindex="-1">Die zwei Modi einer Seite <a class="header-anchor" href="#die-zwei-modi-einer-seite" aria-label="Permalink to &quot;Die zwei Modi einer Seite&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Modus</th><th>Zweck</th></tr></thead><tbody><tr><td><strong>Editor</strong></td><td>Bearbeiten. Sie sehen Blockrahmen und Bedienelemente.</td></tr><tr><td><strong>Anwendung</strong></td><td>Vorschau. Sie sehen die Seite so, wie Besucher sie sehen.</td></tr></tbody></table><p>Über <em>Zurück zur Bearbeitung</em> kommen Sie aus der Vorschau zurück.</p><div class="warning custom-block"><p class="custom-block-title">„Seite&quot; hat drei Bedeutungen</p><p>Achten Sie beim Lesen der Oberfläche darauf, worum es geht:</p><ol><li><strong>Seite (Portal)</strong> — worum es in diesem Kapitel geht.</li><li><strong>Formularseite</strong> — ein Abschnitt in einem mehrseitigen <a href="/formulare/mehrseitige-formulare">Formular</a>.</li><li><strong>Flow-Seite</strong> — eine Seite, die ein <a href="/flows/seiten-in-flows">Flow</a> anzeigt. Technisch ist das eine Seite im Sinne von 1, eingebunden in einen Ablauf.</li></ol><p>Auch zwei Flow-Schritte heißen beide <em>Seite anzeigen</em> — einer ist ein Auslöser, einer eine Aktion.</p></div><h2 id="vom-entwurf-zum-portal" tabindex="-1">Vom Entwurf zum Portal <a class="header-anchor" href="#vom-entwurf-zum-portal" aria-label="Permalink to &quot;Vom Entwurf zum Portal&quot;">​</a></h2><p>Eine Seite ist zunächst nur intern sichtbar. Erst <strong>Portal-Link erstellen</strong> macht sie nach außen erreichbar.</p><p>Das gilt auch für die Vorschau: Wollen Sie die Seite als Portal ansehen, fragt ApptiveGrid</p><blockquote><p><em>Für diese Vorschau als Portal wird ein veröffentlichter Portal-Link benötigt. Möchten Sie ihn jetzt erstellen?</em></p></blockquote><p>→ <a href="/seiten/portal-veroeffentlichen">Portal veröffentlichen</a></p><h2 id="wo-seiten-liegen" tabindex="-1">Wo Seiten liegen <a class="header-anchor" href="#wo-seiten-liegen" aria-label="Permalink to &quot;Wo Seiten liegen&quot;">​</a></h2><p>Seiten gehören zu einem <strong>Space</strong> und stehen in der Seitenleiste unter <strong>Seiten</strong>. Ob dieser Bereich über oder unter den Grids steht, legen Sie in den <a href="/spaces/navigation">Space-Einstellungen</a> fest.</p><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/seiten/seite-erstellen">Seite erstellen und bearbeiten</a></li><li><a href="/seiten/bloecke">Blockübersicht</a></li><li><a href="/seiten/portal-veroeffentlichen">Portal veröffentlichen</a></li></ul>',35)])])}const m=t(a,[["render",s]]);export{b as __pageData,m as default};
